{% macro mask_email(column_name) %}
    CASE
        WHEN {{ column_name }} LIKE '%@%' THEN CONCAT(LEFT({{ column_name }}, 2), '***', SUBSTR({{ column_name }}, POSITION('@' IN {{ column_name }})))
        ELSE '***INVALID_EMAIL***'
    END
{% endmacro %}

{% macro convert_timezone(column_name, target_tz='UTC') %}
    CONVERT_TIMEZONE('UTC', '{{ target_tz }}', {{ column_name }}::timestamp_ntz)
{% endmacro %}

{% macro safe_divide(numerator, denominator) %}
    IFF({{ denominator }} = 0, NULL, {{ numerator }} / {{ denominator }})
{% endmacro %}
